"""The status board's schema rules (board.py), and that both generated files place every block and word where the
schema's layout does. The byte-level proof between the languages is tests/cxx/test_board.cpp and tests/dotnet-board
(check.sh): each reads the known board the other wrote, and a C++ game process writes while C# reads."""
import os
import re
import sys
import tempfile
import unittest

here = os.path.dirname(os.path.abspath(__file__))
folder = os.path.dirname(here)
sys.path.insert(0, folder)
import board  # noqa: E402
import generate  # noqa: E402

with open(board.SCHEMA, encoding="utf-8") as f:
    SCHEMA = f.read()


def text(name):
    with open(os.path.join(folder, generate.OUTPUTS[name]), encoding="utf-8") as f:
        return f.read()


class Schema(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)

    def error(self, old, new):
        self.assertIn(old, SCHEMA)
        path = os.path.join(self.temp.name, "board.toml")
        with open(path, "w", encoding="utf-8") as f:
            f.write(SCHEMA.replace(old, new, 1))
        with self.assertRaises(board.SchemaError) as raised:
            board.load(path)
        return str(raised.exception)

    def test_the_layout(self):
        b, enums, flags, records, blocks = board.load()
        self.assertEqual((b["magic_word"], b["version"], b["size"]), (0x42535A46, 3, 14912))
        self.assertEqual([(x.name, x.offset, x.size) for x in blocks],
                         [("Header", 0, 32), ("Pulse", 64, 16), ("Status", 128, 24), ("Snapshot", 192, 1580),
                          ("ModeHead", 1792, 8824), ("ModeValues", 10624, 1964), ("Events", 12608, 2056),
                          ("Mailbox", 14720, 144)])
        self.assertEqual((records["Racer"].size, records["Event"].size), (52, 32))
        self.assertTrue(all(x.offset % 64 == 0 for x in blocks))

    def test_broken_rules_are_named(self):
        self.assertIn("not aligned", self.error('{ name = "Pad", type = "u16" },\n    { name = "LapMs"',
                                                '{ name = "LapMs"'))
        self.assertIn("endian is little", self.error('endian = "little"', 'endian = "big"'))
        self.assertIn("moved a word", self.error('{ name = "Version", type = "u32", doc = "the launcher\'s layout version" },',
                                                 ""))
        self.assertIn("a ring has a record", self.error("slots = 64", "slots = 1"))
        self.assertIn("unknown keys", self.error('{ name = "Serial", type = "u32"', '{ name = "Serial", typ = "u32"'))
        self.assertIn("no enum of type", self.error('type = "u32", enum = "Phase"', 'type = "u16", enum = "Phase"'))
        self.assertIn("Seq is the generator's", self.error('{ name = "Serial", type = "u32"', '{ name = "Seq", type = "u32"'))
        self.assertIn("a multiple of 4", self.error("size = 128", "size = 130"))
        self.assertIn("only the Header is frozen", self.error('name = "Pulse"\nkind = "plain"',
                                                              'name = "Pulse"\nkind = "plain"\nfrozen = true'))

    def test_the_generated_files_place_every_block_where_the_layout_does(self):
        b, _, _, _, blocks = board.load()
        cxx, cs = text("board_cxx"), text("board_csharp")
        self.assertIn(f"inline constexpr std::size_t SIZE = {b['size']};", cxx)
        self.assertIn(f"public const int Size = {b['size']};", cs)
        for x in blocks:
            with self.subTest(block=x.name):
                self.assertIn(f"inline constexpr std::size_t {board.snake(x.name).upper()} = {x.offset};", cxx)
                self.assertIn(f"public const int {x.name} = {x.offset};", cs)
                if x.kind == "plain":
                    for f in x.fields:
                        self.assertIn(f"{board.snake(x.name).upper()}_{f.snake.upper()} = {x.offset + f.offset};", cxx)
                        self.assertIn(f"public const int {x.name}{f.name} = {x.offset + f.offset};", cs)
        self.assertNotIn("TODO", cxx + cs)
        self.assertEqual(len(re.findall(r"^// Generated by protocol/generate.py", cxx, re.M)), 1)


if __name__ == "__main__":
    unittest.main()
